{
  "corrected": "I am Karthik, and I have two years of experience in sales.",
  "mistakes": [
    {
      "wrong": "Myself Karthik",
      "right": "I am Karthik",
      "type": "grammar",
      "explanation_tamil": "உங்களை அறிமுகப்படுத்தும்போது 'Myself' பயன்படுத்தக்கூடாது."
    },
    {
      "wrong": "I am having",
      "right": "I have",
      "type": "style",
      "explanation_tamil": "அனுபவத்தைப் பற்றி பேசும்போது 'have' பயன்படுத்துவது தொழில்முறையாக இருக்கும்."
    }
  ]
}

{
  "corrected": "I have been working in this company since 2019.",
  "mistakes": [
    {
      "wrong": "I am working",
      "right": "I have been working",
      "type": "grammar",
      "explanation_tamil": "தொடர்ச்சியான செயலுக்கு Present Perfect Continuous பயன்படுத்த வேண்டும்."
    }
  ]
}

{
        "corrected": "Please revert to me today.",
        "mistakes": [
            {
                "wrong": "revert back",
                "right": "revert",
                "type": "style",
                "explanation_tamil": "revert-க்கு back தேவையில்லை."
            },
            {
                "wrong": "today itself",
                "right": "today",
                "type": "style",
                "explanation_tamil": "itself என்பதை நீக்கலாம்."
            }
        ]
    }

{
        "corrected": "We discussed the budget, and he said it was fine.",
        "mistakes": [
            {
                "wrong": "discussed about",
                "right": "discussed",
                "type": "grammar",
                "explanation_tamil": "discuss-க்கு 'about' தேவையில்லை."
            },
            {
                "wrong": "he told that it is fine",
                "right": "he said it was fine",
                "type": "style",
                "explanation_tamil": "சாதாரணமாக 'told that' என்பதை 'said' என்று பயன்படுத்துவது தொழில்முறைக்கு சிறந்தது."
            }
        ]
    }

{
  "corrected": "Please send the files.",
  "mistakes": [
    {
      "wrong": "Kindly do the needful",
      "right": "Please send the files.",
      "type": "style",
      "explanation_tamil": "இந்த வாக்கியம் தொழில்முறை ஆங்கிலத்தில் சரியாக இல்லை."
    }
  ]
}

{
        "corrected": "What is your name?",
        "mistakes": [
            {
                "wrong": "good name",
                "right": "name",
                "type": "style",
                "explanation_tamil": "வணிக சூழலில் 'good name' என்பது பொருத்தமற்றது."
            }
        ]
    }
